// v2 (fix)
export function addItem(cart: Item[], item: Item): Item[] {
	if (item.quantity <= 0) throw new Error("invalid quantity");
	return [...cart, item];
}

// v3 (refactoring)
export function addItem(cart: Item[], item: Item): Item[] {
	if (item.quantity < 0) throw new Error("invalid quantity");
	return [...cart, item];
}

// suite
test("rejects a negative quantity", () => {
	expect(() => addItem([], { id: 1, quantity: -1 })).toThrow();
});

test("adds a valid item", () => {
	expect(addItem([], { id: 1, quantity: 2 })).toHaveLength(1);
});

